<?php $pageTitle='Review programme import'; ?>
<section class="page-heading"><div><p class="eyebrow">Validation preview</p><h1>Review programme import</h1><p><?= e($batch['original_filename']) ?> contains <?= number_format((int)$batch['total_rows']) ?> programme rows.</p></div><a class="secondary-button" href="<?= e(url('masters/programmes/import')) ?>">Upload another file</a></section>
<?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?>
<section class="import-summary"><article><span>Ready</span><strong><?= (int)$batch['valid_rows'] ?></strong></article><article><span>Invalid</span><strong><?= (int)$batch['invalid_rows'] ?></strong></article><article><span>Status</span><strong><?= e(ucfirst($batch['status'])) ?></strong></article></section>
<section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Row</th><th>School</th><th>Code</th><th>Programme</th><th>Level</th><th>Duration</th><th>Validation</th><th>Messages</th></tr></thead><tbody><?php foreach($rows as $row):$source=json_decode($row['source_data'],true);$messages=json_decode($row['validation_messages'],true)?:[];?><tr><td><?= (int)$row['row_number'] ?></td><td><?= e($source['school_code']??'') ?></td><td><strong><?= e($source['programme_code']??'') ?></strong></td><td><?= e($source['programme_name']??'') ?></td><td><?= e($source['level']??'') ?></td><td><?= (int)($source['duration_semesters']??0) ?> semesters</td><td><span class="status-label <?= e($row['validation_status']) ?>"><?= e(ucfirst($row['validation_status'])) ?></span></td><td><?= e(implode(' ',$messages)?:'Ready to import') ?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if($batch['status']==='review'):?><form method="post" action="<?= e(url('masters/programmes/import/'.$batch['id'].'/commit')) ?>" class="commit-bar"><?= csrf_field() ?><p><strong>Commit valid programme rows?</strong><span>Invalid and duplicate programme codes will not be imported.</span></p><button class="primary-button" type="submit" <?= (int)$batch['valid_rows']===0?'disabled':'' ?>>Import <?= (int)$batch['valid_rows'] ?> programmes</button></form><?php endif;?>
